#!/usr/bin/env python3
"""固定版の同梱ソースから Nocturne Intl bundle を再生成する。ネット接続不要。"""
import argparse
import hashlib
import json
import pathlib
import shutil
import subprocess

p = argparse.ArgumentParser(description=__doc__)
p.add_argument('--esbuild', required=True, help='esbuild 0.28.2 の実行ファイル')
p.add_argument('--check', action='store_true', help='製品ファイルは変更せず同一性のみ検証')
a = p.parse_args()
here = pathlib.Path(__file__).resolve().parent
root = here.parent.parent
stage = root / 'build/nocturne-intl'
manifest = json.loads((here / 'manifest.json').read_text(encoding='utf-8'))
esbuild = str(pathlib.Path(a.esbuild).resolve())
version = subprocess.check_output([esbuild, '--version'], text=True, encoding='utf-8').strip()
if version != manifest['esbuild']:
    raise SystemExit('esbuild の固定版が必要: ' + manifest['esbuild'])
for name, expected in manifest['upstreamFilesSha256'].items():
    source = here / name
    if hashlib.sha256(source.read_bytes()).hexdigest() != expected:
        raise SystemExit('上流ソースのハッシュ不一致: ' + name)
    target = stage / 'node_modules' / pathlib.PurePosixPath(name).relative_to('source')
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, target)
for name in ('entry.js', 'lazy-tz.js'):
    shutil.copyfile(here / name, stage / name)
output = stage / 'js_intl.js'
banner = '/* Generated by third_party/formatjs/rebuild.py. FormatJS MIT; Unicode data license and TZDB notices: third_party/formatjs. Do not edit this bundle. */'
subprocess.run([esbuild, str(stage / 'entry.js'), '--bundle', '--format=iife',
                '--platform=browser', '--target=es2023', '--minify', '--legal-comments=inline',
                '--banner:js=' + banner, '--outfile=' + str(output)], check=True, cwd=root)
destination = root / 'user/libc/web/js_intl.js'
data = output.read_bytes()
if a.check:
    if destination.read_bytes() != data:
        raise SystemExit('生成物が一致しません')
else:
    destination.write_bytes(data)
print(str(destination), len(data), 'bytes SHA256', hashlib.sha256(data).hexdigest())
